// Интерфейс посредника
public interface IMediator
{
    void AddUser(User user);
    void AddProduct(Product product);
    void PlaceOrder(string userId, string productId);
}

// Класс посредника
public class OrderMediator : IMediator
{
    private List<User> users = new List<User>();
    private List<Product> products = new List<Product>();

    public void AddUser(User user)
    {
        users.Add(user);
    }

    public void AddProduct(Product product)
    {
        products.Add(product);
    }

    public void PlaceOrder(string userId, string productId)
    {
        var user = users.Find(u => u.Id == userId);
        var product = products.Find(p => p.Id == productId);

        if (user != null && product != null)
        {
            Console.WriteLine($"Order placed by {user.Name} for {product.Name}");
        }
        else
        {
            Console.WriteLine("User or product not found.");
        }
    }
}

